const svg_blyamsBase64 = `data:image/svg+xml;base64,${Buffer.from(svg_blyams).toString('base64')}`

const base64_bg = `data:image/jpeg;base64,`

const fontPath = path.join(process.cwd(), 'public/fonts/InterOGBanners.ttf');
const fontData = readFileSync(fontPath);

// Image metadata
export const size = {
    width: 1200,
    height: 630,
}
 
export const contentType = 'image/png'
export const alt = 'Баннер профиля'

type ImageParametres = {
	params: Promise<{ username: string }>
};

export default async function Image({ params }: ImageParametres) {
    const { username } = await params

    const user = await getUser(username)

    const text = user?.nickname ? `Пользователь - ${user?.nickname}` : ""

    function truncateText(text: string, maxLength: number) {
        return text.length > maxLength ? text.slice(0, maxLength) + '…' : text
    }

    return new ImageResponse(
        (
            <div style={{ display: "flex", background: 'black', width: '100%', height: '100%' }}>
                <img src={base64_bg} alt="" width={1200} height={630} style={{position: "absolute"}} />
                <img src={svg_logoBase64} alt="" width={1200} height={630} />
                <img src={svg_blyamsBase64} alt="" width={1200} height={630} style={{ position: "absolute" }} />
                <span style={{ position: "absolute", top: "250px", left: "80px", fontSize: "64px", color: "#FFFFFFCC", fontFamily: 'Inter', fontWeight: 700, width: "900px" }}>{truncateText(text, 40)}</span>
            </div>
        ),
        {
            width: 1200,
            height: 630,
            fonts: [
                {
                    name: 'Inter',
                    data: fontData,
                    style: 'normal',
                    weight: 700,
                }
            ]
        }
    );
}